import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { NextConfig } from 'next';
import { withSentryConfig } from '@sentry/nextjs';
import packageJson from './package.json';

const projectRoot = path.dirname(fileURLToPath(import.meta.url));

const OPTIONAL_PEERS =
  /^(?:@react-native-async-storage\/async-storage|pino-pretty|encoding|lokijs)$/;
const gitSha = process.env.VERCEL_GIT_COMMIT_SHA?.slice(0, 7) ?? 'local';

const nextConfig: NextConfig = {
  env: {
    NEXT_PUBLIC_APP_VERSION: packageJson.version,
    NEXT_PUBLIC_GIT_SHA: gitSha,
  },
  output: 'standalone',
  async headers() {
    return [
      {
        source: '/(.*)',
        headers: [{ key: 'Referrer-Policy', value: 'origin' }],
      },
    ];
  },
  outputFileTracingRoot: projectRoot,
  turbopack: {
    resolveAlias: {
      '@solana/kit': './src/lib/solana-kit-unavailable.ts',
    },
  },
  webpack: (config, { webpack }) => {
    config.resolve = config.resolve ?? {};
    config.resolve.alias = {
      ...(config.resolve.alias ?? {}),
      '@solana/kit': path.join(
        projectRoot,
        'src/lib/solana-kit-unavailable.ts'
      ),
    };
    config.plugins = config.plugins ?? [];
    config.plugins.push(
      new webpack.IgnorePlugin({
        resourceRegExp: OPTIONAL_PEERS,
      })
    );
    return config;
  },
};

export default withSentryConfig(nextConfig, {
  silent: true,
});

'use client';

import { useEffect, useState } from 'react';
import { DigitalTwinModelViewer } from '@/components/digital-twin/model-viewer';
import { MilestoneChecklist } from '@/components/digital-twin/milestone-checklist';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';
import type { getDigitalTwinProject } from '@/lib/digital-twin-projects';

type DigitalTwinProject = NonNullable<ReturnType<typeof getDigitalTwinProject>>;

type DigitalTwinClientPageProps = {
  project: DigitalTwinProject;
};

export function DigitalTwinClientPage({ project }: DigitalTwinClientPageProps) {
  const [milestones, setMilestones] = useState<ConstructionMilestone[]>(
    project.milestones ?? []
  );

  useEffect(() => {
    setMilestones(project.milestones ?? []);
  }, [project]);

  return (
    <>
      <DigitalTwinModelViewer
        modelUrl={project.modelUrl}
        title={project.title}
        statusLabel={project.statusLabel}
        milestones={project.mode === 'construction' ? milestones : undefined}
      />

      {project.mode === 'operational' && project.energyMetrics ? (
        <section className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
          {project.energyMetrics.map((metric) => (
            <article
              key={metric.label}
              className="rounded-[20px] border border-card-border bg-card-bg p-6 backdrop-blur-xl"
            >
              <p className="text-sm text-gray-400">{metric.label}</p>
              <p className="chakra-petch mt-3 text-3xl font-bold text-white">
                {metric.value}
              </p>
              <p className="mt-3 text-xs text-primary">{metric.helper}</p>
            </article>
          ))}
        </section>
      ) : null}

      {project.mode === 'construction' && milestones.length > 0 ? (
        <MilestoneChecklist milestones={milestones} onChange={setMilestones} />
      ) : null}
    </>
  );
}

'use client';

// cspell:words drei GLTF gltf
import {
  Bounds,
  Environment,
  Html,
  OrbitControls,
  useBounds,
  useGLTF,
} from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import { Suspense, useEffect, useMemo, useState } from 'react';
import { Box3, Vector3, type Mesh, type Object3D } from 'three';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
  statusLabel: string;
  milestones?: ConstructionMilestone[];
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildEnabledNameSet(milestones: ConstructionMilestone[]) {
  const names = new Set<string>();

  milestones.forEach((milestone) => {
    if (!milestone.completed) {
      return;
    }

    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => names.add(nodeName));
    });
  });

  return names;
}

function hasEnabledName(object: Object3D, enabledNames: Set<string>) {
  let current: Object3D | null = object;

  while (current) {
    if (enabledNames.has(current.name)) {
      return true;
    }

    current = current.parent;
  }

  return false;
}

function Model({
  modelUrl,
  statusLabel,
  milestones = [],
}: {
  modelUrl: string;
  statusLabel: string;
  milestones?: ConstructionMilestone[];
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const isOperational = statusLabel === 'Operational';
  const enabledNames = useMemo(
    () => buildEnabledNameSet(milestones),
    [milestones]
  );
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(gltf.scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [gltf.scene]);

  useEffect(() => {
    gltf.scene.traverse((object) => {
      if (!isMesh(object)) {
        object.visible = true;
        return;
      }

      object.visible = isOperational || hasEnabledName(object, enabledNames);
      object.castShadow = object.visible;
      object.receiveShadow = object.visible;
    });

    bounds.refresh(gltf.scene).fit();
  }, [bounds, enabledNames, gltf.scene, isOperational]);

  return <primitive object={gltf.scene} position={modelOffset} />;
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

export function DigitalTwinModelViewer({
  modelUrl,
  title,
  statusLabel,
  milestones,
}: DigitalTwinModelViewerProps) {
  const [showGroundPlane, setShowGroundPlane] = useState(true);
  const [showKeyLight, setShowKeyLight] = useState(true);

  return (
    <section className="overflow-hidden rounded-[28px] border border-card-border bg-card-bg shadow-2xl backdrop-blur-xl">
      <div className="flex flex-col gap-1 border-b border-card-border px-6 py-5 md:flex-row md:items-center md:justify-between">
        <div>
          <p className="text-xs uppercase tracking-[0.35em] text-primary">
            AI-Digital Twin
          </p>
          <h1 className="chakra-petch mt-2 text-3xl font-bold text-white md:text-4xl">
            {title}
          </h1>
        </div>
      </div>

      <div
        className={`relative h-[520px] ${showGroundPlane ? 'bg-[#6f6f6f]' : 'bg-[#808080]'}`}
      >
        <div className="absolute right-4 top-4 z-10 flex flex-col gap-2 rounded-2xl border border-white/20 bg-[#0C0C0D]/75 p-3 text-xs text-gray-200 shadow-xl backdrop-blur-xl">
          <label className="flex items-center justify-between gap-3">
            <span>Ground</span>
            <input
              type="checkbox"
              checked={showGroundPlane}
              onChange={(event) => setShowGroundPlane(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
          <label className="flex items-center justify-between gap-3">
            <span>Light</span>
            <input
              type="checkbox"
              checked={showKeyLight}
              onChange={(event) => setShowKeyLight(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
        </div>

        <Canvas
          camera={{ position: [5, 4, 8], fov: 45 }}
          shadows
          gl={{ antialias: true }}
        >
          <color
            attach="background"
            args={[showGroundPlane ? '#6f6f6f' : '#808080']}
          />
          <ambientLight intensity={0.55} />
          <hemisphereLight args={['#f7f7f7', '#2c2c2c', 0.85]} />
          {showKeyLight ? (
            <directionalLight
              position={[45, 90, 45]}
              intensity={4.8}
              castShadow
              shadow-mapSize={[4096, 4096]}
              shadow-camera-near={1}
              shadow-camera-far={180}
              shadow-camera-left={-90}
              shadow-camera-right={90}
              shadow-camera-top={90}
              shadow-camera-bottom={-90}
              shadow-bias={-0.0002}
              shadow-normalBias={0.08}
            />
          ) : null}
          <Environment preset="city" environmentIntensity={0.35} />
          <Suspense fallback={<LoadingModel />}>
            <Bounds clip margin={1.35}>
              <group>
                {showGroundPlane ? (
                  <group position={[0, 0, 0]}>
                    <gridHelper args={[76, 38, '#d8d8d8', '#a8a8a8']} />
                    <mesh
                      rotation={[-Math.PI / 2, 0, 0]}
                      position={[0, -0.01, 0]}
                      receiveShadow
                    >
                      <planeGeometry args={[76, 76]} />
                      <meshStandardMaterial color="#505050" roughness={0.95} />
                    </mesh>
                  </group>
                ) : null}
                <Model
                  modelUrl={modelUrl}
                  statusLabel={statusLabel}
                  milestones={milestones}
                />
              </group>
            </Bounds>
          </Suspense>
          <OrbitControls makeDefault enableDamping dampingFactor={0.08} />
        </Canvas>
      </div>
    </section>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type MilestoneChecklistProps = {
  milestones: ConstructionMilestone[];
  onChange?: (milestones: ConstructionMilestone[]) => void;
};

export function MilestoneChecklist({
  milestones,
  onChange,
}: MilestoneChecklistProps) {
  const [items, setItems] = useState(milestones);

  useEffect(() => {
    setItems(milestones);
  }, [milestones]);

  const completedCount = useMemo(
    () => items.filter((item) => item.completed).length,
    [items]
  );
  const progress = Math.round((completedCount / items.length) * 100);

  return (
    <section className="rounded-[24px] border border-card-border bg-card-bg p-4 backdrop-blur-xl">
      <div className="flex flex-col gap-4 xl:flex-row xl:items-center">
        <div className="flex shrink-0 flex-col gap-2 xl:w-56">
          <div className="flex items-baseline justify-between gap-3">
            <h2 className="chakra-petch text-xl font-bold text-white">
              Construction Milestones
            </h2>
            <span className="text-xs text-primary">{progress}%</span>
          </div>
          <div className="h-2 overflow-hidden rounded-full bg-[#0C0C0D]">
            <div
              className="h-full rounded-full bg-primary transition-all"
              style={{ width: `${progress}%` }}
            />
          </div>
          <p className="text-xs text-gray-300">
            {completedCount} of {items.length} complete
          </p>
        </div>

        <ul className="flex flex-wrap gap-2">
          {items.map((item) => (
            <li key={item.id}>
              <label
                className={`flex cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-xs capitalize transition ${
                  item.completed
                    ? 'border-primary/50 bg-primary/10 text-gray-100'
                    : 'border-card-border bg-[#0C0C0D]/45 text-gray-400 hover:text-gray-200'
                }`}
              >
                <input
                  type="checkbox"
                  checked={item.completed}
                  aria-label={`Mark ${item.label} complete`}
                  className="h-4 w-4 accent-primary"
                  onChange={(event) => {
                    const completed = event.target.checked;
                    const nextItems = items.map((currentItem) =>
                      currentItem.id === item.id
                        ? { ...currentItem, completed }
                        : currentItem
                    );
                    setItems(nextItems);
                    onChange?.(nextItems);
                  }}
                />
                <span>{item.label}</span>
              </label>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

import type { Metadata } from 'next';
import type { ReactNode } from 'react';
import Script from 'next/script';
import { MainLayout } from '@/components/main-layout';
import { AppProviders } from '@/lib/openfort-config';
import './globals.css';

export const metadata: Metadata = {
  // Openfort's embedded wallet iframe (https://embed.openfort.io/iframe/{pk})
