  // allowed origins. See docs-dev/tasks/task-101-fix-openfort-registration.md.
  referrer: 'origin',
};

export default function RootLayout({ children }: { children: ReactNode }) {
  const recaptchaSiteKey = process.env.NEXT_PUBLIC_RECAPTCHA_SITE_KEY;
